function downloadRawRecovery(text,prompt,error){const payload={schema:'closed-loop-raw-response-recovery/1',failedOperation:'RAW_CAPTURE',canonicalStateChanged:false,jobId:current?.job?.JOB_ID||null,stage:current?.activeStage||null,promptIdentity:prompt?{instructionId:prompt.instructionId||prompt.promptId,bodySha256:prompt.bodySha256||prompt.sha256,contractSha256:prompt.contractSha256,contextSignature:prompt.contextSignature}:null,error:String(error?.message||error),rawResponse:String(text??'')},blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${current?.job?.JOB_ID||'project'}-raw-response-recovery.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),0);}
