const artifactIdFor=()=>`${String(current.job.JOB_ID||'JOB').replace(/[^A-Za-z0-9-]/g,'')}-ARTIFACT-${crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2,8)}`}`;
function logicalFilePath(file){const supplied=String(file?.webkitRelativePath||'').replaceAll('\\','/').replace(/^\/+/,''),fallback=String(file?.name||'').replaceAll('\\','/').replace(/^\/+/,''),raw=supplied||fallback,parts=raw.split('/').filter(Boolean);if(!parts.length||parts.some(part=>part==='.'||part==='..'))throw new Error('Artifact logical path is missing or unsafe.');const logical=supplied&&parts.length>1?parts.slice(1).join('/'):parts.join('/');if(!logical)throw new Error('Artifact logical path is missing.');return logical;}
async function storeArtifactFile(file,stage=current.activeStage,lineage={}){const artifactId=artifactIdFor(),filename=logicalFilePath(file),blob=file.slice(0,file.size,file.type||'application/octet-stream'),stored=await projectStore.putArtifact({artifactId,jobId:current.job.JOB_ID,blob,filename,mediaType:file.type||'application/octet-stream',lineage:{stage,role:core.STAGES[stage-1]?.role||'UNKNOWN',logicalPath:filename,...lineage}});return {stored,view:{artifactId,name:stored.filename,type:stored.mediaType,size:stored.byteSize,sha256:stored.sha256,stage:`STAGE ${String(stage).padStart(2,'0')}`,role:core.STAGES[stage-1]?.role||'UNKNOWN',retainedBytes:true,availability:'IndexedDB Blob bytes persisted and rehashed on read-back.',addedAt:new Date().toISOString()}};}
async function registerStageFiles(fileList){const stage=current.activeStage,created=[];try{if([2,3,4].includes(stage))throw new Error('The original Stage 01 intent file cannot be registered or reused in Stages 02 through 04; use the canonical intentStatements ledger.');const product=stage===21?currentStageProduct():null;if(stage===21&&!product)throw new Error('Reserve the current Stage 21 product execution before selecting finished-product files.');const productId=product?engine.recordId(product,'products'):null,paths=fileList.map(logicalFilePath);if(new Set(paths).size!==paths.length)throw new Error('Selected artifact package contains duplicate logical paths. Use the folder picker for structured packages so directory identity is preserved.');for(const file of fileList)created.push(await storeArtifactFile(file,stage,productId?{productId}:{}));const next=clone(current);for(const item of created){const stored=item.stored;engine.registerArtifactBytes(next,{stage,artifactId:stored.artifactId,filename:stored.filename,mediaType:stored.mediaType,byteSize:stored.byteSize,sha256:stored.sha256,lineage:stored.lineage});next.stages[stage].authorizedFiles.push(item.view);}await persistReplacement(next);announce('artifact bytes saved and verified');render();}catch(error){for(const item of created)try{await projectStore.deleteArtifact?.(item.stored.artifactId,current.job.JOB_ID);}catch{}announce('storage failed');alert(`Artifact storage failed without authorizing metadata-only state: ${error.message||error}`);}}
async function digestFile(file){const bytes=await file.arrayBuffer(),sha256=await globalThis.closedLoopHash.sha256Bytes(bytes);return {name:logicalFilePath(file),type:file.type||'application/octet-stream',size:file.size,sha256};}
